    """Extend a single uninterrupted non-background bar to the right edge."""
    from collections import Counter
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        runs = []
        c = 0
        while c < len(row):
            if row[c] == bg:
                c += 1
                continue
            color = row[c]
            start = c
            while c < len(row) and row[c] == color:
                c += 1
            runs.append((start, c, color))
        if len(runs) == 1:
            start, end, color = runs[0]
            if end < len(row) and all(v == bg for v in row[end:]):
                for j in range(end, len(row)):
                    out[r][j] = 1
    return out

